const items = $input.all()

function fechaCorta(fechaStr) {
  if (!fechaStr) return '-'
  const [y, m, d] = String(fechaStr).slice(0, 10).split('-')
  if (!y || !m || !d) return fechaStr
  return `${d}/${m}/${y.slice(2)}`
}

// Normaliza el teléfono a 549XXXXXXXXXX (formato Evolution API / remoteJid)
function telAR(raw) {
  let d = String(raw || '').replace(/\D/g, '')
  if (!d) return null
  d = d.replace(/^00/, '')
  if (d.startsWith('54')) {
    if (!d.startsWith('549')) d = '549' + d.slice(2)
  } else if (d.startsWith('0')) {
    d = '549' + d.slice(1)
  } else {
    d = '549' + d
  }
  return d
}

return items.map(item => {
  const f = item.json

  const montoFmt = Number(f.monto || 0).toLocaleString('es-AR')

  const hayAdjuntos = !!(
    (Array.isArray(f.comprobantes_adjuntos) && f.comprobantes_adjuntos.length > 0) ||
    f.documento_general
  )

  const camposCuenta = [
    f.cuenta_cbu ? `· CBU: ${f.cuenta_cbu}` : null,
    f.cuenta_alias ? `· Alias: ${f.cuenta_alias}` : null,
    f.cuenta_banco ? `· Banco: ${f.cuenta_banco}` : null,
    f.cuenta_titular ? `· Titular: ${f.cuenta_titular}` : null
  ].filter(Boolean)
  const datosCuenta = camposCuenta.length > 0 ? camposCuenta.join('\n') : '· No se encontraron datos de la cuenta'

  const notaAdjunto = hayAdjuntos ? 'Adjunto encontrarás la factura para tu referencia.\n\n' : ''

  const mensaje_whatsapp = `Hola ${f.contacto_nombre || ''}! 👋
Espero que todo esté yendo bien. Quisiera recordarte que aún no hemos recibido el pago correspondiente a la factura N° ${f.numero_factura || ''} emitida el ${fechaCorta(f.fecha_emision)}.

📄 Detalles de la factura:
· Número: ${f.numero_factura || '-'}
· Vencimiento: ${fechaCorta(f.fecha_vencimiento)}
· Monto total: $${montoFmt}

🏦 Cuenta a depositar:
${datosCuenta}

${notaAdjunto}Si ya has realizado el pago, por favor, ignora este mensaje.

Gracias por tu pronta atención a este asunto.

APSOL - Consultoría Empresarial`

  return {
    json: {
      ...f,
      telefono_wa: telAR(f.contacto_telefono),
      monto_fmt: montoFmt,
      mensaje_whatsapp
    }
  }
})
